def fill_product_skus(apps, schema_editor):
    Product = apps.get_model("goods", "Products")
    Category = apps.get_model("goods", "Categories")
    for category in (
        Category.objects.using(schema_editor.connection.alias)
        .filter(models.Q(slug__isnull=True) | models.Q(slug=""))
        .iterator()
    ):
        category.slug = "category-" + uuid.uuid4().hex
        category.save(update_fields=["slug"], using=schema_editor.connection.alias)
    for product in (
        Product.objects.using(schema_editor.connection.alias).all().iterator()
    ):
        product.sku = f"HOME-{product.pk:05}"
        if not product.slug:
            product.slug = "item-" + uuid.uuid4().hex
        product.save(
            update_fields=["sku", "slug"], using=schema_editor.connection.alias
        )


